{
  "summary": [
    {
      "text": "The domain behind the email address you publish expires on 2026-12-04, and every enquiry, quotation and SEDA submission routed through that mailbox stops with it.",
      "cites": ["f1"]
    },
    {
      "text": "Your contractor grade differs between your own site and a public contractor directory, so a tender panel can rule you out before your submission is even opened.",
      "cites": ["c5"]
    },
    {
      "text": "Your Google rating is strong, and not a single review on the profile has an answer from you; the lone bad rating sits there unexplained.",
      "cites": ["f3", "f7"]
    }
  ],
  "email": {
    "subject": {
      "text": "The email address on your site stops working on 2026-12-04",
      "cites": ["f1"]
    },
    "body": [
      {
        "text": "We read what the public internet says about Eternalgy Sdn Bhd. The domain behind the email address on your own site expires on 2026-12-04, and when it lapses, mail to that address bounces.",
        "cites": ["f1"]
      },
      {
        "text": "There is more of the same: a public contractor directory shows a different grade from the one your site claims, and not one review on your Google profile has a reply.",
        "cites": ["c5", "f3"]
      },
      {
        "text": "All of it is public today, so any customer, bank or tender panel checking you can see it before you get the chance to explain.",
        "cites": ["f1", "c5", "f3"]
      }
    ]
  },
  "titles": [
    {
      "id": "f1",
      "text": "The domain behind the email address you publish expires, and every enquiry sent there stops with it."
    },
    {
      "id": "f2",
      "text": "Your site sends none of the standard security headers, and a bank or insurer reviewing it will see that."
    },
    {
      "id": "f3",
      "text": "Not one review on your Google profile has a reply, and the bad one sits there unexplained."
    },
    {
      "id": "f4",
      "text": "Your site is built for Google, not for the AI assistants buyers now ask for a shortlist of contractors."
    },
    {
      "id": "c1",
      "text": "Your head office unit number differs across 3 sources. Couriers, auditors and site visitors may arrive at the wrong door."
    },
    {
      "id": "c2",
      "text": "Enquiries land in different mailboxes depending on which page a customer reads, so half your quote requests can go unread."
    },
    {
      "id": "c3",
      "text": "Your two sites list different branches, so a customer near one of your listed offices sees no office on the other site."
    },
    {
      "id": "c4",
      "text": "Three published totals for completed projects disagree, and the lowest sits on a public directory beside your name."
    },
    {
      "id": "c5",
      "text": "Your contractor grade differs between your own site and a public directory. A tender panel may rule you out before reading your bid."
    },
    {
      "id": "c6",
      "text": "An employer profile gives your company the wrong legal form, and contracts and payments are matched on the registered name."
    },
    {
      "id": "c7",
      "text": "Three sources name three different websites for you, so enquiries land in three places and none of them is authoritative."
    },
    {
      "id": "n1",
      "text": "A contractor directory places you in a different state from your head office. Worth checking before your next tender."
    }
  ],
  "proof": {
    "id": "f1",
    "why": "The owner can confirm the expiry in a minute with a public lookup, the mailbox and every enquiry through it stop on that date, and renewing it leaves every other problem on the page untouched."
  }
}

